// Included only by this experiment's build.py. Production sources never load it.
const OFFICE_FIDELITY={ready:false,frames:0,textureBytes:0,started:performance.now(),scope:'office1-4; cat-box travel/pop/stop, one ginger turntable, board tiles, cubby faces; native arrival animation'};
const fidelityTextures=Object.create(null),fidelitySurfaces=Object.create(null);
let fidelityBoardDrawing=false;
window.__officeFidelityCat=null;
const fidelityCatVariants=[[],[],[]];
let fidelityFloorLight=null;
function fidelityBlend(dst,src,alpha){
  const inv=255-alpha;
  return (255<<24)|(((((src>>>16)&255)*alpha+((dst>>>16)&255)*inv+127)/255|0)<<16)|(((((src>>>8)&255)*alpha+((dst>>>8)&255)*inv+127)/255|0)<<8)|(((src&255)*alpha+(dst&255)*inv+127)/255|0);
}
function fidelityPixel(r,x,y,light=1){
  const p=(y*r.width+x)*4,d=r.rgba;
  let red=Math.min(255,Math.round(d[p]*light)),green=Math.min(255,Math.round(d[p+1]*light)),blue=Math.min(255,Math.round(d[p+2]*light));
  if(grayscale)red=green=blue=Math.round(red*.299+green*.587+blue*.114);
  return (255<<24)|(blue<<16)|(green<<8)|red;
}
function fidelityTexture(id,rgba,w,h,dx,dy){
  const pixels=new Uint8Array(w*h);for(let i=0;i<pixels.length;i++)pixels[i]=rgba[i*4+3]?C.CREAM:EMPTY;
  return {id,dx,dy,w:w/4,h:h/4,x:AX+dx,y:AY+dy,width:w,height:h,rgba,pixels};
}

// Pilot 2: RGBA animation extensions, driven exclusively by existing board poses.
let fidelityPose=null,fidelityBoxPose=null;
const fidelityLoose=[null,{},{}],fidelityExpressions=[null,[],[]],fidelityFold=[];
const fidelityArtHits={box:0,expression:0,stretch:0,hop:0,sit:0,nap:0,fold:0,rim:0};
function fidelityVariant(r,id,sy=1,alpha=1){
  const c=document.createElement('canvas');c.width=r.width;c.height=r.height;
  const src=document.createElement('canvas');src.width=r.width;src.height=r.height;
  src.getContext('2d').putImageData(new ImageData(new Uint8ClampedArray(r.rgba),r.width,r.height),0,0);
  const ctx=c.getContext('2d');ctx.globalAlpha=alpha;
  ctx.drawImage(src,0,c.height*(1-sy),c.width,c.height*sy);
  const v=fidelityTexture(id,ctx.getImageData(0,0,c.width,c.height).data,c.width,c.height,r.dx,r.dy);
  OFFICE_FIDELITY.textureBytes+=v.rgba.byteLength+v.pixels.byteLength;return v;
}
function fidelityUse(r,kind){window.__officeFidelityCat=r;fidelityArtHits[kind]++;}
function fidelityPrepareAnimation(){
  for(let coat=1;coat<=2;coat++){
    const name=FIDELITY_OFFICE_PROFILE.catCoats[coat-1];
    fidelityLoose[coat].front={};fidelityLoose[coat].back={};
    for(const view of FIDELITY_OFFICE_PROFILE.animation.views)for(const pose of FIDELITY_OFFICE_PROFILE.animation.poses){
      const r=fidelityTextures['anim-'+name+'-'+view+'-'+pose];
      fidelityLoose[coat][view][pose]=[r,fidelityVariant(r,r.id+'-motion',pose==='nap'?1.06:.96)];
    }
    for(let head=0;head<2;head++){
      const suffix=head===1?'-opposite':'';
      fidelityExpressions[coat][head]=FIDELITY_OFFICE_PROFILE.animation.expressions.map(p=>fidelityTextures['anim-'+name+'-box-'+p+suffix]);
    }
  }
  for(let fold=0;fold<5;fold++){
    const r=fidelityTextures['anim-box-fold'+Math.min(3,fold)];
    // Native fade starts only after the box is flat. Other fold states share
    // their one texture rather than retaining sixteen unused copies each.
    fidelityFold[fold]=Array.from({length:17},(_,n)=>fold<4||n===0?r:fidelityVariant(r,r.id+'-fade'+n,1,1-n/16));
  }
  // A separate foreground cutout keeps a supported cat behind the tray lip.
  const open=fidelityFold[0][0],rgba=new Uint8ClampedArray(open.rgba);
  for(let y=0;y<open.height;y++)for(let x=0;x<open.width;x++){
    const edge=open.height*.72-Math.abs(x-open.width*.5)*.47;
    if(y<edge)rgba[(y*open.width+x)*4+3]=0;
  }
  window.fidelityRim=fidelityTexture('fidelity-tray-rim',rgba,open.width,open.height,open.dx,open.dy);
  OFFICE_FIDELITY.textureBytes+=rgba.byteLength+fidelityRim.pixels.byteLength;
  const box=buildCatBox,loose=buildLoose,takeoff=buildPaperTakeoff,empty=buildBox,draw=drawBoardCat,drawBox=drawBoardBox;
  buildCatBox=function(coat,dir,head,ears,eyes,bob,stretch,red){
    box(coat,dir,head,ears,eyes,bob,stretch,red);
    if(!fidelityPose||coat<1||coat>2)return;
    let r=fidelityCatVariants[coat][head];
    if(head<2){const n=stretch?3:ears===2?2:eyes?0:ears===1?1:-1;if(n>=0){r=fidelityExpressions[coat][head][n];fidelityArtHits.expression++;}}
    fidelityUse(r,'box');
  };
  buildLoose=function(coat,pose,frame,look){
    loose(coat,pose,frame,look);if(!fidelityPose||coat<1||coat>2)return;
    const o=fidelityPose,view=o.dir>=2?'back':'front';
    const kind=pose==='curl'?'nap':pose==='stretch'?'stretch':pose==='walk'?'hop':'sit';
    fidelityUse(fidelityLoose[coat][view][kind][frame&1],kind);
  };
  buildPaperTakeoff=function(coat,dir,frame){
    const result=takeoff(coat,dir,frame);if(!fidelityPose||coat<1||coat>2)return result;
    const kind=frame===0?'stretch':'hop';
    fidelityUse(fidelityLoose[coat][dir>=2?'back':'front'][kind][frame&1],kind);return result;
  };
  buildBox=function(fold,red,mirror){
    empty(fold,red,mirror);if(!fidelityBoxPose)return;
    const fade=Math.min(16,Math.max(0,Math.round(fidelityBoxPose.boxFade*16)));
    fidelityUse(fidelityFold[fold][fade],'fold');
  };
  drawBoardCat=function(o,tr){fidelityPose=o;try{draw(o,tr);}finally{fidelityPose=null;window.__officeFidelityCat=null;}};
  drawBoardBox=function(o,tr){fidelityBoxPose=o;try{drawBox(o,tr);}finally{fidelityBoxPose=null;window.__officeFidelityCat=null;}};
  OFFICE_FIDELITY.scope='office1-4 pilot2; matching travel expressions, stretch/takeoff/turn/curl/nap/wake/leave and tray folding; native sim and depth';
}

