 for(const [id,point,R]of[['left-working',[24,32,32],3.8],['rear-return',[114,24,20.15],1.2],['rear-roof',[168,24,31.2],1.1],['left-roof',[24,112,26.15],1.1]]){socket(p,point,[0,0,1],R);if(id==='rear-return')span(p,point,[114,24,24],R);}
