 for(const x of[166,170])quad(p,[x,18,26.5],[x,25,30.3],[x,18,30.3],[x,18,26.5],'gold',.87);solid('bank inlet bracket',[165.5,17,26.5,170.5,26.5,31.3]);
 p.origins=[{id:'rear-working',point:[66,24,24],support:[60,19,0,72,30,25.5]},{id:'rear-return',point:[114,24,20.15],support:[78,14,17,154,43,20.2]},{id:'rear-roof',point:[168,24,31.2],support:[165.5,17,29.5,170.5,26.5,31.3]},{id:'left-working',point:[24,32,32],support:[8,22,30,40,48,32.1]},{id:'left-roof',point:[24,112,26.15],support:[9.5,108,24,41.5,134,26.2]}];
