 span(p,[24,36,36],[26,36,36],2.8);{const a=[26,36,36],e=[26,38.5,34],axis=norm(e.map((v,i)=>v-a[i])),back=e.map((v,i)=>v-axis[i]*1.5);tube(p,[a,e],[2.8,4.2]);annulus(p,e,axis,4.3,3.5,'gold');tube(p,[back,e],3.5,'shaft');annulus(p,back,axis,3.5,0,'shaft');}
