  const cz=2.6,R=2.6,point=(r,a,front)=>wall==='Y'?[cx+r*Math.cos(a),cy+front,cz+r*Math.sin(a)]:[cx+front,cy+r*Math.cos(a),cz+r*Math.sin(a)];
