  const dir=Math.floor(index/3),open=index%3,gap=[.3,1.4,4.5][open],dx=[1,0,-1,0][dir],dy=[0,1,0,-1][dir],rect=(p,q,P,Q,z,m,t=1)=>poly([[p,q],[P,q],[P,Q],[p,Q]].map(([u,v])=>[u*dx-v*dy,u*dy+v*dx]),z,m,t);Object.assign(out,{direction:dir,open,gap});
